<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { request } from '../api/client'
import { state, selectProject, notify } from '../store/workbench'
import { kinds, relationshipTypes } from '../lib/display'
import type { RecordData } from '../types'
import StatusPill from '../components/StatusPill.vue'
const route=useRoute(),router=useRouter(),batch=ref<RecordData>({entities:[],relationships:[],keys:{},proposals:[]}),error=ref(''),busy=ref(false),q=ref(''),offset=ref(0)
const editor=ref(false),editing=ref<RecordData|null>(null),history=ref<RecordData[]>([]),impact=ref<RecordData|null>(null)
const form=reactive({kind:'Requirement',name:'',description:'',criteria:'',attributes:'{}',status:'draft',reason:'',actor:state.actor||'本地维护者'})
const relation=reactive({source:'',target:'',type:'DEPENDS_ON',reason:''})
const release=ref('v1')
const rows=computed(()=>batch.value.entities.filter((e:RecordData)=>e.name.includes(q.value)||kinds[e.kind]?.includes(q.value)))
const pid=computed(()=>String(route.params.projectId||state.projectId))
let generation=0
async function load(){const token=++generation;error.value='';try{const data=await request(`/workbench/projects/${pid.value}/knowledge?limit=200&offset=${offset.value}`);if(token===generation)batch.value=data}catch(e){error.value=(e as Error).message}}
watch(()=>[route.params.projectId,state.initialized],async()=>{if(!state.initialized||!route.params.projectId)return;try{if(state.projectId!==pid.value)await selectProject(pid.value);await load()}catch(e){error.value=(e as Error).message}},{immediate:true})
async function proposed(p:RecordData){notify('提案已建立，尚未提交知识。');await router.push(`/projects/${pid.value}/proposals/${p.id}`)}
async function importCourse(){busy.value=true;try{const result=await request<RecordData>(`/workbench/projects/${pid.value}/course-import`,{release:release.value,actor:form.actor});await proposed(result.proposal)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function edit(e:RecordData|null){editing.value=e;Object.assign(form,{kind:e?.kind||'Requirement',name:e?.name||'',description:e?.description||'',criteria:(e?.attributes?.acceptance_criteria||[]).join('\n'),attributes:JSON.stringify(e?.attributes||{},null,2),status:e?.status||'draft',reason:''});history.value=[];impact.value=null;editor.value=true}
async function save(){busy.value=true;error.value='';try{const attrs=JSON.parse(form.attributes);if(form.kind==='Requirement')attrs.acceptance_criteria=form.criteria.split('\n').map(s=>s.trim()).filter(Boolean);let p:RecordData;if(editing.value){const e=editing.value;p=await request('/operations/proposals',{project_id:pid.value,title:'修订 '+form.name,actor:form.actor,changes:[{op:'update_entity',id:e.id,data:{expected_version:e.version,name:form.name,description:form.description,status:form.status,attributes:attrs,evidence:e.evidence,provenance:{actor:form.actor,source_uri:'urn:workbench:manual',source_revision:String(e.version+1),change_reason:form.reason,nature:'human_confirmed'}}}]})}else{const result=await request<RecordData>('/operations/ingestions',{project_id:pid.value,source_uri:'urn:workbench:manual:'+crypto.randomUUID(),source_revision:'v1',format:'json',actor:form.actor,title:'新建 '+form.name,content:JSON.stringify({entities:[{key:'item',kind:form.kind,name:form.name,description:form.description,attributes:attrs}],relationships:[]})});p=result.proposal}editor.value=false;await proposed(p)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function viewHistory(e:RecordData){edit(e);try{history.value=await request(`/entities/${e.id}/history`);impact.value=await request(`/operations/impact?project_id=${pid.value}&entity_id=${e.id}`)}catch(e){error.value=(e as Error).message}}
async function addRelation(){busy.value=true;try{const source=batch.value.entities.find((e:RecordData)=>e.id===relation.source),target=batch.value.entities.find((e:RecordData)=>e.id===relation.target);const p=await request<RecordData>(`/workbench/projects/${pid.value}/relationships`,{type:relation.type,source_id:source.id,target_id:target.id,source_version:source.version,target_version:target.version,rationale:relation.reason,provenance:{actor:form.actor,source_uri:'urn:workbench:manual',source_revision:'v1',change_reason:relation.reason,nature:'inference'}});await proposed(p)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function check(){try{impact.value=await request(`/operations/consistency?project_id=${pid.value}`)}catch(e){error.value=(e as Error).message}}
</script>
<template><section class="panel project-panel"><h2>项目知识</h2><p>这里显示项目全部知识，不需要先建立流程。创建与修订先形成提案，审阅提交后才保存。</p><div v-if="error" class="info-box error" role="alert">{{ error }}</div><div class="inline-actions"><RouterLink :to="`/projects/${pid}/proposals`" class="button secondary">项目提案</RouterLink><button class="button primary" @click="edit(null)">新建知识</button><button class="button secondary" @click="load">刷新知识</button><button class="button secondary" @click="check">检查一致性</button></div>
<details class="scenario-card"><summary>选课教学案例：导入一轮知识</summary><p>先完成本轮提案与流程，再导入下一轮。导入只建立待审提案，后续创建流程时绑定已有知识。</p><label>教学版本 <select v-model="release"><option>v1</option><option>v1.1</option><option>v1.2</option></select></label><label>操作署名 <input v-model="form.actor" required></label><button class="button secondary" :disabled="busy||!form.actor.trim()" @click="importCourse">提出选课知识提案</button></details>
<label class="field">搜索知识<input v-model="q" placeholder="按名称或类型筛选当前页"></label><p>{{ batch.total || 0 }} 项知识（包含项目自身）</p><div class="table-scroll"><table class="knowledge-table"><thead><tr><th>知识名称</th><th>类型</th><th>状态 / 版本</th><th>操作</th></tr></thead><tbody><tr v-for="e in rows" :key="e.id"><td>{{ e.name }}<small class="section-label">{{ batch.keys[e.id] || '' }}</small></td><td>{{ kinds[e.kind] }}</td><td><StatusPill :status="e.status"/> v{{ e.version }}</td><td><button v-if="e.kind!=='Project'" class="text-button" @click="edit(e)">修订</button> <button class="text-button" @click="viewHistory(e)">历史与影响</button></td></tr></tbody></table></div><div class="inline-actions"><button class="button secondary" :disabled="offset===0" @click="offset-=200;load()">上一页</button><button class="button secondary" :disabled="offset+200>=batch.total" @click="offset+=200;load()">下一页</button></div>
<details v-if="editor" open class="editor-box"><summary>{{ editing ? '修订知识与查看历史' : '新建知识草稿' }}</summary><form @submit.prevent="save"><label class="field">类型<select v-model="form.kind" :disabled="!!editing"><option v-for="(label,key) in kinds" v-show="!['Project','Relationship'].includes(key)" :key="key" :value="key">{{ label }}</option></select></label><label class="field">名称<input v-model="form.name" required></label><label class="field">说明<textarea v-model="form.description" rows="3"></textarea></label><label v-if="form.kind==='Requirement'" class="field">验收条件（每行一条）<textarea v-model="form.criteria" rows="4"></textarea></label><label v-if="editing" class="field">生命周期<select v-model="form.status"><option value="draft">草稿</option><option value="active">生效</option><option value="deprecated">弃用</option><option value="archived">归档</option></select></label><details><summary>类型属性（高级 JSON 编辑）</summary><textarea v-model="form.attributes" rows="10" class="json-editor"></textarea><p>组件职责用 responsibility，接口协议用 protocol，模型结构用 schema_definition；服务端仍按类型校验。</p></details><label class="field">操作署名<input v-model="form.actor" required></label><label class="field">变更依据<textarea v-model="form.reason" required></textarea></label><button class="button primary" :disabled="busy||editing?.kind==='Project'||editing?.status==='archived'">建立待审提案</button> <button type="button" class="button secondary" @click="editor=false">收起</button></form><h3 v-if="history.length">不可变修订历史</h3><details v-for="h in history" :key="h.version"><summary>v{{ h.version }} · {{ h.name }} · {{ h.provenance.change_reason }}</summary><pre>{{ JSON.stringify(h,null,2) }}</pre></details></details>
<details v-if="impact" open class="editor-box"><summary>影响或一致性检查结果（待人工复核）</summary><pre>{{ JSON.stringify(impact,null,2) }}</pre></details>
<details class="editor-box"><summary>项目关系与新增关系提案</summary><table class="knowledge-table"><tr v-for="r in batch.relationships" :key="r.id"><td>{{ batch.entities.find((e:RecordData)=>e.id===r.source_id)?.name || r.source_id }}</td><td>{{ relationshipTypes[r.type] }}</td><td>{{ batch.entities.find((e:RecordData)=>e.id===r.target_id)?.name || r.target_id }}</td><td><StatusPill :status="r.status"/></td></tr></table><form @submit.prevent="addRelation"><label class="field">源知识<select v-model="relation.source" required><option value="">请选择</option><option v-for="e in batch.entities" :key="e.id" :value="e.id">{{ e.name }}</option></select></label><label class="field">关系类型<select v-model="relation.type"><option v-for="(label,key) in relationshipTypes" :value="key" :key="key">{{ label }}</option></select></label><label class="field">目标知识<select v-model="relation.target" required><option value="">请选择</option><option v-for="e in batch.entities" :key="e.id" :value="e.id">{{ e.name }}</option></select></label><label class="field">关系依据<textarea v-model="relation.reason" required></textarea></label><button class="button primary" :disabled="busy||!form.actor.trim()">建立关系提案</button></form></details></section></template>
